using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class SceneTabsOperations
{
    private readonly ActorTimelineOperations _timeline=new();private readonly ActorDefinitionOperations _definitions=new();
    public void audio_to_scene(TabBar owner,AudioStream? stream,string label){var timeline=Timeline(owner);if(timeline==null||stream==null)return;var workspace=Workspace(owner,"audio")!;int active=Active(owner);var documents=Documents(owner);if(active<0||active>=documents.Count||Kind(documents[active].AsGodotDictionary())!="audio"){workspace.Call("notice","Return to the source audio document and send it to Scene again.");return;}var source=documents[active].AsGodotDictionary();if(source.GetValueOrDefault("id","").AsString().Length==0)source["id"]=_data.new_id();string sourceId=source["id"].AsString();var association=workspace.Get("session").AsGodotObject().Get("document").AsGodotObject().Get("scene_binding").AsGodotDictionary();string sceneId=source.GetValueOrDefault("scene_id","").AsString();var binding=new Settings();if(association.Count>0){int destination=scene_index_for_association(owner,association);if(destination<0){string path=association.GetValueOrDefault("scene_path","").AsString();string detail=path.Length>0?"Open the saved destination scene and send again to update its original actor.":"The original unsaved destination scene is no longer open.";choose_audio_destination(owner,stream,label,sourceId,detail+(path.Length>0?" Saved destination: "+path:""));return;}sceneId=documents[destination].AsGodotDictionary()["id"].AsString();string actorId=association.GetValueOrDefault("actor_id","").AsString();if(actorId.Length>0)binding["actor_id"]=actorId;}if(audio_scene_index_for_id(owner,sceneId)<0){choose_audio_destination(owner,stream,label,sourceId,"The original destination scene is closed or was never selected. Choose where to add the rendered audio.");return;}place_audio_in_scene(owner,stream,label,sourceId,sceneId,binding,false);}
    public void choose_audio_destination(TabBar owner,AudioStream stream,string label,string sourceId,string reason){var dialog=new ConfirmationDialog{Title="Choose audio destination",OkButtonText="Add rendered audio"};owner.AddChild(dialog);var column=new VBoxContainer();dialog.AddChild(column);column.AddChild(new Label{Text=reason+" A new audio actor will be created; no actor in another scene will be replaced.",AutowrapMode=TextServer.AutowrapMode.WordSmart,CustomMinimumSize=new Vector2(430,0)});var choice=new OptionButton();column.AddChild(choice);choice.AddItem("Create a new scene");choice.SetItemMetadata(0,"");foreach(var value in Documents(owner)){var document=value.AsGodotDictionary();if(Kind(document)!="scene")continue;string id=document.GetValueOrDefault("id","").AsString();choice.AddItem(document.GetValueOrDefault("name","Scene").AsString()+" ["+(id.Length>6?id[^6..]:id)+"]");choice.SetItemMetadata(choice.ItemCount-1,id);}dialog.Confirmed+=()=>{string sceneId=choice.GetItemMetadata(choice.Selected).AsString();if(sceneId.Length==0){new_scene(owner);if(Active(owner)<0||Active(owner)>=Documents(owner).Count){dialog.QueueFree();return;}sceneId=Documents(owner)[Active(owner)].AsGodotDictionary().GetValueOrDefault("id","").AsString();}place_audio_in_scene(owner,stream,label,sourceId,sceneId,new Settings(),true);dialog.QueueFree();};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(new Vector2I(500,220));}
    public void place_audio_in_scene(TabBar owner,AudioStream stream,string label,string sourceId,string sceneId,Settings binding,bool rebind)
    {
        var workspace=Workspace(owner,"audio")!;if(audio_document_index(owner,sourceId)<0){workspace.Call("notice","The source audio tab was closed. No scene actor was changed.");return;}int index=audio_scene_index_for_id(owner,sceneId);if(index<0){workspace.Call("notice","The selected destination scene was closed. The rendered source has not replaced any actor. Send it again to choose a destination.");return;}capture_current(owner);open_index(owner,index);var timeline=Timeline(owner)!;var model=timeline.Get("model").As<RefCounted>();if(binding.Count>0){var actor=_timeline.actor_for_id(model,binding.GetValueOrDefault("actor_id","").AsString());if(actor==null||actor.Get("type_id").AsString()!="audio"){choose_audio_destination(owner,stream,label,sourceId,"The original audio actor no longer exists in its source scene.");return;}var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());if(clip==null){workspace.Call("notice","The bound audio actor no longer has an editable clip. No source was replaced.");return;}var before=_timeline.audio_snapshot(model,actor);var after=before.Duplicate(true);var values=actor.Get("values").AsGodotDictionary().Duplicate(true);after["values"]=values;values[new StringName("audio")]=stream;string editable=audio_saved_document_path(owner,sourceId);if(editable.Length>0)values[new StringName("audio_workspace_document")]=editable;else values.Remove(new StringName("audio_workspace_document"));after["offset"]=0.0;after["duration"]=stream.GetLength()/Math.Max(.05,clip.Get("playback_speed").AsDouble());var history=model.Get("history").As<UndoRedo>();var action=new SceneTabsAudioRestoreAction(model,before,after);history.CreateAction("Update from Audio Workspace");history.AddDoMethod(new Callable(action,nameof(SceneTabsAudioRestoreAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(SceneTabsAudioRestoreAction.restore_before)));history.AddDoReference(action);history.CommitAction();return;}var definition=_definitions.get_definition(timeline.Get("registry").As<RefCounted>(),"audio");if(definition==null){workspace.Call("notice","The scene audio actor definition is unavailable.");return;}var initial=new Settings{[new StringName("audio")]=stream};string path=audio_saved_document_path(owner,sourceId);if(path.Length>0)initial[new StringName("audio_workspace_document")]=path;var created=_timeline.create_actor(model,definition,timeline.Get("canvas").As<Control>().Get("playhead").AsDouble(),initial);if(created!=null){var actor=_timeline.actor_for_id(model,created.Get("actor_id").AsString());actor?.Set("display_name",label);model.EmitSignal("changed");int sourceIndex=audio_document_index(owner,sourceId);if(sourceIndex>=0){Documents(owner)[sourceIndex].AsGodotDictionary()["scene_id"]=sceneId;set_audio_scene_association(owner,sourceId,sceneId,created.Get("actor_id").AsString());}}
    }
    public void confirm_audio_close(TabBar owner,int index){if(index<0||index>=Documents(owner).Count)return;var document=Documents(owner)[index].AsGodotDictionary();if(document.GetValueOrDefault("id","").AsString().Length==0)document["id"]=_data.new_id();string id=document["id"].AsString();var dialog=new ConfirmationDialog{Title="Unsaved audio composition",DialogText=document["name"].AsString()+" has unsaved changes.",OkButtonText="Save"};dialog.AddButton("Discard",false,"discard");owner.AddChild(dialog);dialog.Confirmed+=()=>{dialog.QueueFree();owner.Call("_save_audio_close_driver",id);};dialog.CustomAction+=action=>{int current=audio_document_index(owner,id);if(action=="discard"&&current>=0)owner.Call("close_scene",current,true);dialog.QueueFree();};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(new Vector2I(440,150));}
    public RefCounted? prepare_audio_close_save(TabBar owner,string id){int index=audio_document_index(owner,id);if(index<0)return null;capture_current(owner);open_index(owner,index);return Workspace(owner,"audio")!.Get("session").As<RefCounted>();}
    public void finish_audio_close_save(TabBar owner,string id,RefCounted session){int index=audio_document_index(owner,id);if(index>=0&&!session.Get("dirty").AsBool())owner.Call("close_scene",index,true);}
}
